const express = require('express');
const app = express();

// User profile data store (simulated)
const userProfiles = {
  'alice': { name: 'Alice', bio: 'Security researcher' },
  'bob': { name: 'Bob', bio: 'Frontend developer' }
};

// Middleware to parse JSON bodies
app.use(express.json());

// Route to fetch user profile
app.get('/profile/:username', (req, res) => {
  const username = req.params.username;

  // Validate username against whitelist pattern
  if (!/^[a-zA-Z0-9_]{1,20}$/.test(username)) {
    return res.status(400).json({ error: 'Invalid username format' });
  }

  const profile = userProfiles[username];
  if (!profile) {
    return res.status(404).json({ error: 'User not found' });
  }

  // Set Content-Type to text/plain to prevent HTML rendering
  res.setHeader('Content-Type', 'text/plain; charset=utf-8');

  // Send user-controlled data as plain text (not HTML)
  res.send(`Name: ${profile.name}\nBio: ${profile.bio}`);
});

// Route that echoes user input directly
app.post('/echo', (req, res) => {
  const userInput = req.body.input || '';

  // Validate input length and characters
  if (typeof userInput !== 'string' || userInput.length > 500) {
    return res.status(400).json({ error: 'Invalid input' });
  }

  // Set Content-Type to text/plain to prevent XSS via HTML rendering
  res.setHeader('Content-Type', 'text/plain; charset=utf-8');

  // Echo user input as plain text - safe because browser won't render as HTML
  res.send(userInput);
});

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

