        dataSource.setPassword(dbPassword);
        return dataSource;
    }
}

import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import java.util.Base64;

public class ETagGenerator {

    private static final String CACHE_VERSION = "v1.2.0";

    /**
     * 生成ETag用于HTTP缓存验证，不涉及密码存储或安全认证
     * 使用MD5仅为了快速计算内容指纹，非安全用途
     */
    public String generateETag(String resourceContent) {
        if (resourceContent == null) {
            throw new IllegalArgumentException("Resource content cannot be null");
        }

        // 1. 规范化输入，避免缓存键冲突
        String normalizedContent = resourceContent.trim();

        // 2. 添加版本号防止缓存污染
        String contentWithVersion = CACHE_VERSION + ":" + normalizedContent;

        try {
            // 3. 使用MD5计算内容指纹（仅缓存用途）
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(contentWithVersion.getBytes(StandardCharsets.UTF_8));

            // 4. 编码为安全的ETag格式（Base64 URL-safe）
            String etag = Base64.getUrlEncoder().withoutPadding()
                    .encodeToString(digest);

            // 5. 添加弱验证器标记（W/前缀表示非强验证）
            return "W/\"" + etag + "\"";
        } catch (Exception e) {
            // 6. 失败时回退到基于时间的ETag（不泄露内容）
            long timestamp = System.currentTimeMillis();
            return "W/\"time-" + timestamp + "\"";
        }
    }

    /**
     * 验证客户端提供的ETag是否匹配
     */
    public boolean validateETag(String clientEtag, String currentContent) {
        if (clientEtag == null || currentContent == null) {
            return false;
        }

        // 仅接受弱验证器格式（W/前缀），拒绝其他格式
        if (!clientEtag.startsWith("W/\"")) {
            return false;
        }

        // 重新生成ETag并比对
        String currentEtag = generateETag(currentContent);
        return currentEtag.equals(clientEtag);
    }
}

import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.DocumentBuilder;
import org.w3c.dom.Document;
import org.xml.sax.InputSource;
import java.io.StringReader;

public class XMLParser {

    public Document parseXML(String xmlContent) throws Exception {
        // 创建 DocumentBuilderFactory 实例
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // 启用安全处理特性，限制 XML 处理中的资源消耗
        factory.setFeature("http://javax.xml.XMLConstants/feature/secure-processing", true);

        // 禁用外部 DTD 和外部实体解析（防御 XXE）
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

        // 禁用外部 DTD 加载
        factory.setAttribute("http://xml.org/sax/features/validation", false);

        // 创建 DocumentBuilder
        DocumentBuilder builder = factory.newDocumentBuilder();

        // 解析 XML 内容
        InputSource inputSource = new InputSource(new StringReader(xmlContent));
        return builder.parse(inputSource);
    }

    public static void main(String[] args) {
        XMLParser parser = new XMLParser();

        // 测试用例：包含外部实体的恶意 XML
        String maliciousXML = "<?xml version=\"1.0\"?>\n" +
            "<!DOCTYPE foo [\n" +
            "  <!ENTITY xxe SYSTEM \"file:///etc/passwd\">\n" +
            "]>\n" +
            "<foo>&xxe;</foo>";

        try {
            Document doc = parser.parseXML(maliciousXML);
            System.out.println("XML parsed successfully");
        } catch (Exception e) {
            System.out.println("XML parsing failed: " + e.getMessage());
        }
    }
}

import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.xml.sax.InputSource;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.DocumentBuilder;
import java.io.StringReader;

public class XMLConfigParser {
    private static final String[] ALLOWED_KEYS = {"server", "port", "timeout"};

    public static String parseConfig(String xmlInput) {
        try {
            // 1. 配置DocumentBuilderFactory，禁用外部实体
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            factory.setXIncludeAware(false);
            factory.setExpandEntityReferences(false);

            DocumentBuilder builder = factory.newDocumentBuilder();
            Document doc = builder.parse(new InputSource(new StringReader(xmlInput)));

            Element root = doc.getDocumentElement();
            String configKey = root.getAttribute("key");
            String configValue = root.getAttribute("value");

            // 2. 校验configKey必须在白名单中
            boolean isValidKey = false;
            for (String allowedKey : ALLOWED_KEYS) {
                if (allowedKey.equals(configKey)) {
                    isValidKey = true;
                    break;
                }
            }
            if (!isValidKey) {
                return "error: invalid key";
            }

            // 3. 使用XML转义库净化configValue（防御XPath注入）
            String sanitizedValue = sanitizeXmlValue(configValue);
            return "config " + configKey + " = " + sanitizedValue;
        } catch (Exception e) {
            return "error: " + e.getMessage();
        }
    }

    private static String sanitizeXmlValue(String value) {
        if (value == null) {
            return "";
        }
        // 转义XML特殊字符，防止XPath注入
        return value.replace("&", "&amp;")
                   .replace("<", "&lt;")
                   .replace(">", "&gt;")
                   .replace("\"", "&quot;")
                   .replace("'", "&apos;");
    }
}

